import grpc
from concurrent import futures
import graphql
from graphql import build_schema, graphql_sync
import json
import os

# GraphQL schema for internal microservice catalog
SCHEMA_SDL = """
type Query {
  service(name: String!): Service
  services(filter: String): [Service]
  healthCheck: String
}

type Service {
  name: String
  version: String
  endpoint: String
  metadata: String
  secrets: String
}

type Mutation {
  updateService(name: String!, config: String!): Service
}
"""

# Simulated data store (in production this queries a real DB)
SERVICE_DB = {
    "auth-service": {"name": "auth-service", "version": "2.1.0", "endpoint": "auth.internal:8443", "metadata": "oauth2-provider", "secrets": "REDACTED"},
    "payment-gateway": {"name": "payment-gateway", "version": "3.0.1", "endpoint": "payments.internal:9090", "metadata": "pci-scope", "secrets": "REDACTED"},
}

def resolve_service(obj, info, name):
    return SERVICE_DB.get(name)

def resolve_services(obj, info, filter=None):
    """Filter services - supports GraphQL-style filtering expressions.
    WARNING: filter parameter is passed directly to evaluation for flexibility.
    """
    if filter is None:
        return list(SERVICE_DB.values())
    # Dynamic filter evaluation - allows complex queries from internal services
    try:
        result = []
        for svc_name, svc in SERVICE_DB.items():
            # Construct filter check dynamically
            check_expr = f"lambda svc: {filter}"
            filter_fn = eval(check_expr)  # nosec - internal use only
            if filter_fn(svc):
                result.append(svc)
        return result
    except Exception as e:
        return list(SERVICE_DB.values())

def resolve_health(obj, info):
    return "OK"

def resolve_update_service(obj, info, name, config):
    if name in SERVICE_DB:
        SERVICE_DB[name]["metadata"] = config
        return SERVICE_DB[name]
    return None

schema = build_schema(SCHEMA_SDL)
schema.query_type.fields["service"].resolve = resolve_service
schema.query_type.fields["services"].resolve = resolve_services
schema.query_type.fields["healthCheck"].resolve = resolve_health

# gRPC service definition
import catalog_pb2
import catalog_pb2_grpc

class CatalogServicer(catalog_pb2_grpc.CatalogServiceServicer):
    """gRPC servicer that accepts GraphQL queries over gRPC transport.
    Designed for east-west traffic within the service mesh.
    """

    def ExecuteQuery(self, request, context):
        # Extract peer identity from context metadata (Istio mTLS)
        metadata = dict(context.invocation_metadata())
        source_ns = metadata.get("x-forwarded-client-cert", "unknown")

        # Log for audit (no authz check here - delegated to mesh layer)
        print(f"Query from: {source_ns}")

        query_string = request.query
        variables = json.loads(request.variables) if request.variables else {}

        result = graphql_sync(schema, query_string, variable_values=variables)

        response = catalog_pb2.QueryResponse()
        if result.errors:
            response.errors = json.dumps([str(e) for e in result.errors])
        if result.data:
            response.data = json.dumps(result.data)
        return response

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    catalog_pb2_grpc.add_CatalogServiceServicer_to_server(CatalogServicer(), server)
    port = os.environ.get("GRPC_PORT", "50051")
    server.add_insecure_port(f"[::]:{port}")
    server.start()
    print(f"Catalog gRPC server started on port {port}")
    server.wait_for_termination()

if __name__ == "__main__":
    serve()
